static std::uint64_t mixU64Fingerprint(std::uint64_t hash, const std::uint64_t value)
{
	for (std::size_t shift = 0; shift < 64; shift += 8)
	{
		const auto byte = static_cast<std::uint8_t>((value >> shift) & 0xffU);
		hash ^= static_cast<std::uint64_t>(byte);
		hash *= 0x00000100000001b3ULL;
	}
	return hash;
}

static int keypointFingerprintFrameLimit()
{
	const char* value = std::getenv("TRIORB_CUDA_FEATURE_KEYPOINT_FINGERPRINT_MAX_FRAMES");
	if (value == nullptr || value[0] == '\0')
		return 0;

	char* end = nullptr;
	const auto parsed = std::strtol(value, &end, 10);
	if (end == value)
		return 0;
	if (parsed < 0)
		return 0;
	if (parsed > 1000)
		return 1000;
	return static_cast<int>(parsed);
}

static bool shouldLogKeypointFingerprint(const std::string& sensorId, const std::uint64_t timestamp)
{
	if (sensorId.empty())
		return false;

	const auto frameLimit = keypointFingerprintFrameLimit();
	if (frameLimit <= 0)
		return false;

	static std::mutex mutex;
	static std::unordered_map<std::string, std::set<std::uint64_t>> loggedTimestampsBySensor;

	std::lock_guard<std::mutex> lock(mutex);
	auto& loggedTimestamps = loggedTimestampsBySensor[sensorId];
	if (loggedTimestamps.find(timestamp) != loggedTimestamps.end())
		return true;
	if (static_cast<int>(loggedTimestamps.size()) >= frameLimit)
		return false;
	loggedTimestamps.insert(timestamp);
	return true;
}

struct ByteImageFingerprint
{
	int rows = 0;
	int cols = 0;
	int minValue = 0;
	int maxValue = 0;
	int nonzeroCount = 0;
	double meanValue = 0.0;
	std::uint64_t hash = 0xcbf29ce484222325ULL;
};

static ByteImageFingerprint computeByteImageFingerprint(const Mat& image)
{
	ByteImageFingerprint stats;
	if (image.empty())
		return stats;

	stats.rows = image.rows;
	stats.cols = image.cols;
	stats.minValue = std::numeric_limits<int>::max();
	stats.maxValue = std::numeric_limits<int>::min();
	std::uint64_t sum = 0U;

	stats.hash = mixU64Fingerprint(stats.hash, static_cast<std::uint64_t>(image.rows));
	stats.hash = mixU64Fingerprint(stats.hash, static_cast<std::uint64_t>(image.cols));
	for (int y = 0; y < image.rows; ++y)
	{
		const auto* row = image.ptr<uchar>(y);
		for (int x = 0; x < image.cols; ++x)
		{
			const auto value = static_cast<int>(row[x]);
			stats.minValue = std::min(stats.minValue, value);
			stats.maxValue = std::max(stats.maxValue, value);
			stats.nonzeroCount += value != 0 ? 1 : 0;
			sum += static_cast<std::uint64_t>(value);
			stats.hash = mixU64Fingerprint(stats.hash, static_cast<std::uint64_t>(value));
		}
	}

	const auto pixelCount = static_cast<double>(image.rows) * static_cast<double>(image.cols);
	stats.meanValue = pixelCount > 0.0 ? static_cast<double>(sum) / pixelCount : 0.0;
	if (stats.minValue == std::numeric_limits<int>::max())
		stats.minValue = 0;
	if (stats.maxValue == std::numeric_limits<int>::min())
		stats.maxValue = 0;
	return stats;
}

static std::uint64_t coordinateFingerprint(const Vec2s& point)
{
	std::uint64_t hash = 0xcbf29ce484222325ULL;
	hash = mixU64Fingerprint(hash, static_cast<std::uint64_t>(static_cast<std::uint16_t>(point[0])));
	hash = mixU64Fingerprint(hash, static_cast<std::uint64_t>(static_cast<std::uint16_t>(point[1])));
	return hash;
}

static std::uint64_t orderedCoordinateFingerprint(const std::vector<Vec2s>& points)
{
	std::uint64_t hash = 0xcbf29ce484222325ULL;
	for (const auto& point : points)
		hash = mixU64Fingerprint(hash, coordinateFingerprint(point));
	return hash;
}

static std::uint64_t unorderedCoordinateSetFingerprint(std::vector<Vec2s> points)
{
	std::sort(points.begin(), points.end(), [](const Vec2s& lhs, const Vec2s& rhs) {
		if (lhs[1] != rhs[1])
			return lhs[1] < rhs[1];
		return lhs[0] < rhs[0];
	});

	std::uint64_t hash = 0xcbf29ce484222325ULL;
	for (const auto& point : points)
		hash = mixU64Fingerprint(hash, coordinateFingerprint(point));
	return hash;
}

struct BlockCountStats
{
	int nonzeroCount = 0;
	int minValue = 0;
	int p50Value = 0;
	int p90Value = 0;
	int maxValue = 0;
	double meanValue = 0.0;
	std::uint64_t hash = 0xcbf29ce484222325ULL;
};

static BlockCountStats computeBlockCountStats(std::vector<int> blockCounts)
{
	BlockCountStats stats;
	if (blockCounts.empty())
		return stats;

	std::uint64_t sum = 0U;
	for (const auto count : blockCounts)
	{
		stats.nonzeroCount += count > 0 ? 1 : 0;
		sum += static_cast<std::uint64_t>(count);
		stats.hash = mixU64Fingerprint(stats.hash, static_cast<std::uint64_t>(count));
	}

	std::sort(blockCounts.begin(), blockCounts.end());
	const auto percentileAt = [&blockCounts](const double percentile) {
		const auto lastIndex = static_cast<double>(blockCounts.size() - 1U);
		const auto rawIndex = static_cast<std::size_t>(std::llround(lastIndex * percentile));
		return blockCounts[std::min(rawIndex, blockCounts.size() - 1U)];
	};

	stats.minValue = blockCounts.front();
	stats.p50Value = percentileAt(0.50);
	stats.p90Value = percentileAt(0.90);
	stats.maxValue = blockCounts.back();
	stats.meanValue = static_cast<double>(sum) / static_cast<double>(blockCounts.size());
	return stats;
}

/**
 * @brief 候補列を固定 4x4 または 8x8 cell へ集計する。
 * @param points `(x,y)` 候補列。例: full recapture の全候補。
 * @param pointCount `points` の有効要素数。
 * @param imageRows pyramid image の高さ。
 * @param imageCols pyramid image の幅。
 * @param gridSize 一辺の cell 数。例: 4 または 8。
 * @return row-major cell count の fingerprint と分布。
 * @example 4x4 の場合は 16 cell、8x8 の場合は 64 cell を返す。
 */
static BlockCountStats computeGridOccupancy(const Vec2s* points, const int pointCount,
	const int imageRows, const int imageCols, const int gridSize)
{
	if (points == nullptr || pointCount < 0 || imageRows <= 0 || imageCols <= 0 || gridSize <= 0)
		return BlockCountStats{};

	std::vector<int> cellCounts(static_cast<std::size_t>(gridSize) * static_cast<std::size_t>(gridSize), 0);
	for (int index = 0; index < pointCount; ++index)
	{
		const auto x = std::max(0, std::min(static_cast<int>(points[index][0]), imageCols - 1));
		const auto y = std::max(0, std::min(static_cast<int>(points[index][1]), imageRows - 1));
		const auto cellX = std::min((x * gridSize) / imageCols, gridSize - 1);
		const auto cellY = std::min((y * gridSize) / imageRows, gridSize - 1);
		cellCounts[static_cast<std::size_t>(cellY * gridSize + cellX)] += 1;
	}
	return computeBlockCountStats(std::move(cellCounts));
}

struct FastPrecapRuntimeAudit
{
	bool deterministic = false;
	bool fullCapture = false;
	bool canonicalizerApplied = false;
	unsigned int initialCount = 0;
	unsigned int recaptureCapacity = 0;
	unsigned int recaptureCount = 0;
	unsigned int storedCount = 0;
	unsigned int selectedCount = 0;
	unsigned int droppedCount = 0;
	std::uint64_t selectedOrderDigest = 0xcbf29ce484222325ULL;
	const Vec2s* fullCaptureCoordinates = nullptr;
	fast_precap_detail::SelectionStatus status = fast_precap_detail::SelectionStatus::NOT_REQUIRED;
};

