	mask2 |= ((d1 & 2) >> 1) << 5;

	mask1 |= (d2 & 1) << 13;
	mask2 |= ((d2 & 2) >> 1) << 13;



	d1 = diffType(v, (C[1] >> (3 * 8)) & 0xff, th);
	d2 = diffType(v, (C[3] >> (3 * 8)) & 0xff, th);

	mask1 |= (d1 & 1) << 7;
	mask2 |= ((d1 & 2) >> 1) << 7;

	mask1 |= (d2 & 1) << 15;
	mask2 |= ((d2 & 2) >> 1) << 15;
}

// 1 -> v > x + th
// 2 -> v < x - th
// 0 -> not a keypoint
__device__ __forceinline__ bool isKeyPoint(int mask1, int mask2)
{
	return (__popc(mask1) > 8 && (c_table[(mask1 >> 3) - 63] & (1 << (mask1 & 7)))) ||
		(__popc(mask2) > 8 && (c_table[(mask2 >> 3) - 63] & (1 << (mask2 & 7))));
}

__global__ void calcKeypointsKernel(const PtrStepSzb img, const PtrStepb mask, short2* kpLoc,
	const unsigned int maxKeypoints, const int threshold, unsigned int* d_counter)
{
	const int j = threadIdx.x + blockIdx.x * blockDim.x + 3;
	const int i = threadIdx.y + blockIdx.y * blockDim.y + 3;

	if (i < img.rows - 3 && j < img.cols - 3 && mask(i, j))
	{
		int v;
		uint C[4] = { 0,0,0,0 };

		C[2] |= static_cast<uint>(img(i - 3, j - 1)) << 8;
		C[2] |= static_cast<uint>(img(i - 3, j));
		C[1] |= static_cast<uint>(img(i - 3, j + 1)) << (3 * 8);

		C[2] |= static_cast<uint>(img(i - 2, j - 2)) << (2 * 8);
		C[1] |= static_cast<uint>(img(i - 2, j + 2)) << (2 * 8);

		C[2] |= static_cast<uint>(img(i - 1, j - 3)) << (3 * 8);
		C[1] |= static_cast<uint>(img(i - 1, j + 3)) << 8;

		C[3] |= static_cast<uint>(img(i, j - 3));
		v = static_cast<int>(img(i, j));
		C[1] |= static_cast<uint>(img(i, j + 3));

		int d1 = diffType(v, C[1] & 0xff, threshold);
		int d2 = diffType(v, C[3] & 0xff, threshold);

		if ((d1 | d2) == 0)
			return;

		C[3] |= static_cast<uint>(img(i + 1, j - 3)) << 8;
		C[0] |= static_cast<uint>(img(i + 1, j + 3)) << (3 * 8);

		C[3] |= static_cast<uint>(img(i + 2, j - 2)) << (2 * 8);
		C[0] |= static_cast<uint>(img(i + 2, j + 2)) << (2 * 8);

		C[3] |= static_cast<uint>(img(i + 3, j - 1)) << (3 * 8);
		C[0] |= static_cast<uint>(img(i + 3, j));
		C[0] |= static_cast<uint>(img(i + 3, j + 1)) << 8;

		int mask1 = 0;
		int mask2 = 0;

		calcMask(C, v, threshold, mask1, mask2);

		if (isKeyPoint(mask1, mask2))
		{
			const unsigned int ind = atomicInc(d_counter, (unsigned int)(-1));

			if (ind < maxKeypoints)
				kpLoc[ind] = make_short2(j, i);
		}
	}
}

/**
 * @brief calcKeypoints 直後の入力画像、mask、候補点、block 分布を標準出力へ記録する。
 * @param image FAST 検出へ渡した pyramid level 画像。例: 640x480 の `CV_8U`。
 * @param mask FAST 検出へ渡した有効領域 mask。例: border だけ 0、それ以外 255。
 * @param keypoints `calcKeypointsKernel` が書いた候補点行列。例: row0 に `(x,y)` が入る。
 * @param rawCount atomic counter が返した候補数。例: 2380。
 * @param cappedCount `nfeatures` で cap 済みの出力候補数。例: 500。
 * @param nfeatures 出力上限。例: `maxpoints`。
 * @param threshold FAST threshold。例: 20。
 * @param block kernel の block 形状。例: 32x8。
 * @param grid kernel の grid 形状。例: 20x60。
 * @param sensorId 診断対象 sensor id。例: `cam_front_l`。
 * @param timestamp frame timestamp。例: ROS nanosecond timestamp。
 * @param slotIndex multi-camera batch 内 index。例: 0。
 * @param level pyramid level。例: 0。
 * @param precapAudit overflow recapture と固定 hash 選択の保存則。
 * @return なし。
 * @example 入力: `TRIORB_CUDA_FEATURE_KEYPOINT_FINGERPRINT_MAX_FRAMES=8` を設定した BISON-01 run。
 * @example 出力: `[cuda_feature_calc_keypoints_fingerprint] ... image_hash=... xy_set_hash=...`。
 */
static void logCalcKeypointsFingerprint(
	const GpuMat& image, const GpuMat& mask, const GpuMat& keypoints, const unsigned int rawCount,
	const int cappedCount, const int nfeatures, const int threshold, const dim3& block, const dim3& grid,
	const char* sensorId, const std::uint64_t timestamp, const int slotIndex, const int level,
	const FastPrecapRuntimeAudit& precapAudit)
{
	const std::string sensorIdString = sensorId != nullptr ? sensorId : "";
	if (!shouldLogKeypointFingerprint(sensorIdString, timestamp))
		return;

	Mat imageHost;
	Mat maskHost;
	Mat keypointsHost;
	image.download(imageHost);
	mask.download(maskHost);
	keypoints.download(keypointsHost);
	if (imageHost.empty() || maskHost.empty() || keypointsHost.empty() || grid.x == 0 || grid.y == 0
		|| block.x == 0 || block.y == 0)
		return;

	const auto imageStats = computeByteImageFingerprint(imageHost);
	const auto maskStats = computeByteImageFingerprint(maskHost);
	const Vec2s* pointRows = keypointsHost.ptr<Vec2s>(EfficientFeatures::LOCATION_ROW);

	std::vector<Vec2s> coordinates;
	coordinates.reserve(static_cast<std::size_t>(cappedCount));
	std::vector<int> blockCounts(static_cast<std::size_t>(grid.x) * static_cast<std::size_t>(grid.y), 0);
	for (int i = 0; i < cappedCount; ++i)
	{
		const auto point = pointRows[i];
		coordinates.push_back(point);

		const auto blockX = std::min(
			std::max((static_cast<int>(point[0]) - 3) / static_cast<int>(block.x), 0),
			static_cast<int>(grid.x) - 1);
		const auto blockY = std::min(
			std::max((static_cast<int>(point[1]) - 3) / static_cast<int>(block.y), 0),
			static_cast<int>(grid.y) - 1);
		const auto blockIndex = static_cast<std::size_t>(blockY) * static_cast<std::size_t>(grid.x)
			+ static_cast<std::size_t>(blockX);
		if (blockIndex < blockCounts.size())
			blockCounts[blockIndex] += 1;
	}

	const auto blockStats = computeBlockCountStats(blockCounts);
	const auto validFullCapture = precapAudit.fullCaptureCoordinates != nullptr;
	const auto rawOccupancyAvailable = validFullCapture || rawCount == static_cast<unsigned int>(cappedCount);
	const auto* rawCoordinates = validFullCapture ? precapAudit.fullCaptureCoordinates : coordinates.data();
	const auto rawCoordinateCount = validFullCapture ? static_cast<int>(precapAudit.recaptureCount) : cappedCount;
	std::vector<Vec2s> rawCoordinateVector;
	if (rawOccupancyAvailable)
		rawCoordinateVector.assign(rawCoordinates, rawCoordinates + rawCoordinateCount);
	const auto rawOccupancy4 = rawOccupancyAvailable
		? computeGridOccupancy(rawCoordinates, rawCoordinateCount, image.rows, image.cols, 4) : BlockCountStats{};
	const auto selectedOccupancy4 = computeGridOccupancy(
		coordinates.data(), cappedCount, image.rows, image.cols, 4);
	const auto rawOccupancy8 = rawOccupancyAvailable
		? computeGridOccupancy(rawCoordinates, rawCoordinateCount, image.rows, image.cols, 8) : BlockCountStats{};
	const auto selectedOccupancy8 = computeGridOccupancy(
		coordinates.data(), cappedCount, image.rows, image.cols, 8);
	const auto countConservation = precapAudit.selectedCount + precapAudit.droppedCount == rawCount;
	const auto selectedCountExpected = precapAudit.selectedCount
		== std::min(rawCount, static_cast<unsigned int>(nfeatures));
	const auto recaptureCountMatch = !precapAudit.fullCapture
		|| precapAudit.initialCount == precapAudit.recaptureCount;
	const auto storedCountMatch = !precapAudit.fullCapture
		|| precapAudit.recaptureCount == precapAudit.storedCount;
	std::ostringstream streamLine;
	streamLine << std::setprecision(6)
		<< "[cuda_feature_calc_keypoints_fingerprint]"
		<< " sensor_id=" << sensorIdString
		<< " timestamp=" << timestamp
		<< " slot_index=" << slotIndex
		<< " level=" << level
		<< " threshold=" << threshold
		<< " nfeatures=" << nfeatures
		<< " image_rows=" << imageStats.rows
		<< " image_cols=" << imageStats.cols
		<< " grid_x=" << grid.x
		<< " grid_y=" << grid.y
		<< " block_x=" << block.x
		<< " block_y=" << block.y
		<< " raw_candidate_count=" << rawCount
		<< " capped_candidate_count=" << cappedCount
		<< " deterministic=" << (precapAudit.deterministic ? 1 : 0)
		<< " precap_policy=" << (precapAudit.deterministic
			? fast_precap_detail::SPLITMIX64_PRECAP_POLICY : "legacy_atomic_prefix")
		<< " precap_full_capture=" << (precapAudit.fullCapture ? 1 : 0)
		<< " precap_full_capture_valid=" << (validFullCapture ? 1 : 0)
		<< " precap_applied=" << (precapAudit.canonicalizerApplied ? 1 : 0)
		<< " precap_status=" << fast_precap_detail::selectionStatusName(precapAudit.status)
		<< " precap_initial_count=" << precapAudit.initialCount
		<< " precap_recapture_capacity=" << precapAudit.recaptureCapacity
		<< " precap_recapture_count=" << precapAudit.recaptureCount
		<< " precap_stored_count=" << precapAudit.storedCount
		<< " precap_stored_count_source=" << (precapAudit.fullCapture
			? "kernel_capacity_proof" : "not_applicable")
		<< " precap_selected_count=" << precapAudit.selectedCount
		<< " precap_dropped_count=" << precapAudit.droppedCount
		<< " precap_count_conservation=" << (countConservation ? 1 : 0)
		<< " precap_selected_count_expected=" << (selectedCountExpected ? 1 : 0)
		<< " precap_recapture_count_match=" << (recaptureCountMatch ? 1 : 0)
		<< " precap_stored_count_match=" << (storedCountMatch ? 1 : 0)
		<< " raw_occupancy_available=" << (rawOccupancyAvailable ? 1 : 0)
		<< std::scientific
		<< " image_mean=" << imageStats.meanValue
		<< std::defaultfloat
		<< " image_min=" << imageStats.minValue
		<< " image_max=" << imageStats.maxValue
		<< " image_nonzero=" << imageStats.nonzeroCount
		<< " mask_valid_count=" << maskStats.nonzeroCount
		<< " image_hash=" << std::hex << std::setw(16) << std::setfill('0') << imageStats.hash
		<< " mask_hash=" << std::setw(16) << maskStats.hash
		<< " xy_order_hash=" << std::setw(16) << orderedCoordinateFingerprint(coordinates)
		<< " xy_set_hash=" << std::setw(16) << unorderedCoordinateSetFingerprint(coordinates)
		<< " raw_xy_order_hash=" << std::setw(16) << orderedCoordinateFingerprint(rawCoordinateVector)
		<< " raw_xy_set_hash=" << std::setw(16) << unorderedCoordinateSetFingerprint(rawCoordinateVector)
		<< " block_count_hash=" << std::setw(16) << blockStats.hash
		<< " precap_seed=" << std::setw(16) << fast_precap_detail::SPLITMIX64_PRECAP_SEED
		<< " precap_selected_order_digest=" << std::setw(16) << precapAudit.selectedOrderDigest
		<< " raw_occupancy_4x4_hash=" << std::setw(16) << rawOccupancy4.hash
		<< " selected_occupancy_4x4_hash=" << std::setw(16) << selectedOccupancy4.hash
		<< " raw_occupancy_8x8_hash=" << std::setw(16) << rawOccupancy8.hash
		<< " selected_occupancy_8x8_hash=" << std::setw(16) << selectedOccupancy8.hash
		<< std::dec << std::setfill(' ')
		<< " block_nonzero_count=" << blockStats.nonzeroCount
		<< " block_count_min=" << blockStats.minValue
		<< " block_count_p50=" << blockStats.p50Value
		<< " block_count_p90=" << blockStats.p90Value
		<< " block_count_max=" << blockStats.maxValue
		<< " raw_occupancy_4x4_nonzero=" << rawOccupancy4.nonzeroCount
		<< " selected_occupancy_4x4_nonzero=" << selectedOccupancy4.nonzeroCount
		<< " raw_occupancy_4x4_min=" << rawOccupancy4.minValue
		<< " raw_occupancy_4x4_max=" << rawOccupancy4.maxValue
		<< " selected_occupancy_4x4_min=" << selectedOccupancy4.minValue
		<< " selected_occupancy_4x4_max=" << selectedOccupancy4.maxValue
		<< " raw_occupancy_8x8_nonzero=" << rawOccupancy8.nonzeroCount
		<< " selected_occupancy_8x8_nonzero=" << selectedOccupancy8.nonzeroCount
		<< " raw_occupancy_8x8_min=" << rawOccupancy8.minValue
		<< " raw_occupancy_8x8_max=" << rawOccupancy8.maxValue
		<< " selected_occupancy_8x8_min=" << selectedOccupancy8.minValue
		<< " selected_occupancy_8x8_max=" << selectedOccupancy8.maxValue
		<< std::scientific
		<< " block_count_mean=" << blockStats.meanValue;

	const int sampleCount = std::min(cappedCount, 3);
	for (int i = 0; i < sampleCount; ++i)
	{
		streamLine << std::defaultfloat
			<< " sample" << i << "_x=" << coordinates[static_cast<std::size_t>(i)][0]
			<< " sample" << i << "_y=" << coordinates[static_cast<std::size_t>(i)][1];
	}
	std::cout << streamLine.str() << std::endl;
}

/**
 * @brief FAST 候補を検出し、deterministic overflow だけ固定 hash で image-area cap へ選択する。
 * @param image pyramid level の `CV_8U` 画像。
 * @param mask FAST 判定の有効領域 mask。
 * @param keypoints 既存 `cvRound(0.1*image.area())` cap の出力行列。
 * @param nfeatures 呼出側で計算済みの既存 area cap。
 * @param threshold FAST threshold。
 * @param d_buffer counter と後続 suppression が共有する device scratch。
 * @param h_buffer counter 回収用の pinned host scratch。
 * @param stream camera slot 専用 CUDA stream。
 * @param deterministic true の overflow 時だけ full recapture と hash 選択を許可する。
 * @param fullCaptureBuffer image area 分を再利用する device 候補 buffer。
 * @param fullCaptureHostBuffer image area 分を再利用する pinned host 候補 buffer。
 * @param sensorId 診断 sensor id。
 * @param timestamp 診断 frame timestamp。
 * @param slotIndex multi-camera slot index。
 * @param level pyramid level。
 * @return なし。count/座標契約不一致は例外で fail-close する。
 * @example raw=3609, cap=3608 なら full recapture 後の固定 rank 先頭3608点を返す。
 */
void calcKeypoints(const GpuMat& image, const GpuMat& mask, GpuMat& keypoints, int nfeatures, int threshold,
	GpuMat& d_buffer, HostMem& h_buffer, cudaStream_t stream, const bool deterministic,
	GpuMat& fullCaptureBuffer, HostMem& fullCaptureHostBuffer, const char* sensorId,
	const std::uint64_t timestamp, const int slotIndex, const int level)
{
	CV_Assert(keypoints.rows >= 1 && keypoints.cols >= nfeatures && keypoints.type() == CV_32F);
	CV_Assert(nfeatures > 0 && d_buffer.size().area() >= 1 && h_buffer.createMatHeader().total() >= 1U);

	const dim3 block(32, 8);
	const dim3 grid(divUp(image.cols - 6, block.x), divUp(image.rows - 6, block.y));

	short2* kpLoc = keypoints.ptr<short2>(0);
	unsigned int* d_count = d_buffer.ptr<unsigned int>(0);
	unsigned int* h_count = h_buffer.createMatHeader().ptr<unsigned int>();

	CUDA_CHECK(cudaMemsetAsync(d_count, 0, sizeof(unsigned int), stream));

	calcKeypointsKernel<<<grid, block, 0, stream>>>(image, mask, kpLoc, nfeatures, threshold, d_count);
	CUDA_CHECK(cudaGetLastError());

	CUDA_CHECK(cudaMemcpyAsync(h_count, d_count, sizeof(unsigned int), cudaMemcpyDeviceToHost, stream));
	CUDA_CHECK(cudaStreamSynchronize(stream));

	FastPrecapRuntimeAudit precapAudit;
	precapAudit.deterministic = deterministic;
	precapAudit.initialCount = *h_count;
	precapAudit.selectedCount = std::min(*h_count, static_cast<unsigned int>(nfeatures));
	precapAudit.droppedCount = *h_count - precapAudit.selectedCount;
	keypoints.cols = static_cast<int>(precapAudit.selectedCount);

	if (deterministic && fast_precap_detail::requiresCanonicalPrecap(*h_count, nfeatures))
	{
		const auto imageArea = static_cast<std::size_t>(image.size().area());
		const auto coordinateLimit = static_cast<std::size_t>(std::numeric_limits<short>::max());
		if (imageArea > std::numeric_limits<unsigned int>::max()
			|| static_cast<std::size_t>(image.rows) > coordinateLimit
			|| static_cast<std::size_t>(image.cols) > coordinateLimit
			|| fullCaptureBuffer.type() != CV_16SC2
			|| static_cast<std::size_t>(fullCaptureBuffer.size().area()) < imageArea)
		{
			keypoints.cols = 0;
			CV_Error(Error::StsOutOfRange, "deterministic FAST full-capture buffer or coordinate range is invalid");
		}

		Mat fullCaptureHost = fullCaptureHostBuffer.createMatHeader();
		if (fullCaptureHost.type() != CV_16SC2 || fullCaptureHost.total() < imageArea)
		{
			keypoints.cols = 0;
			CV_Error(Error::StsOutOfRange, "deterministic FAST host full-capture buffer is too small");
		}

		precapAudit.fullCapture = true;
		precapAudit.recaptureCapacity = static_cast<unsigned int>(imageArea);
		CUDA_CHECK(cudaMemsetAsync(d_count, 0, sizeof(unsigned int), stream));
		calcKeypointsKernel<<<grid, block, 0, stream>>>(image, mask,
			fullCaptureBuffer.ptr<short2>(0), precapAudit.recaptureCapacity, threshold, d_count);
		CUDA_CHECK(cudaGetLastError());
		CUDA_CHECK(cudaMemcpyAsync(h_count, d_count, sizeof(unsigned int), cudaMemcpyDeviceToHost, stream));
		CUDA_CHECK(cudaStreamSynchronize(stream));

		precapAudit.recaptureCount = h_count[0];
		precapAudit.storedCount = std::min(precapAudit.recaptureCount, precapAudit.recaptureCapacity);
		const auto copyCount = std::min(precapAudit.storedCount, precapAudit.recaptureCapacity);
		if (copyCount > 0U)
		{
			CUDA_CHECK(cudaMemcpyAsync(fullCaptureHost.ptr<Vec2s>(), fullCaptureBuffer.ptr<short2>(0),
				static_cast<std::size_t>(copyCount) * sizeof(Vec2s), cudaMemcpyDeviceToHost, stream));
			CUDA_CHECK(cudaStreamSynchronize(stream));
		}

		fast_precap_detail::SelectionAudit selectionAudit;
		precapAudit.status = fast_precap_detail::canonicalizeFullFastCapture(
			fullCaptureHost.ptr<Vec2s>(), precapAudit.initialCount, precapAudit.recaptureCount,
			precapAudit.storedCount, precapAudit.recaptureCapacity, static_cast<std::size_t>(nfeatures),
			image.rows, image.cols, &selectionAudit);
		precapAudit.selectedCount = static_cast<unsigned int>(selectionAudit.selectedCount);
		precapAudit.droppedCount = static_cast<unsigned int>(selectionAudit.droppedCount);
		precapAudit.selectedOrderDigest = selectionAudit.selectedOrderDigest;
		if (precapAudit.status != fast_precap_detail::SelectionStatus::SELECTED)
		{
			logCalcKeypointsFingerprint(image, mask, keypoints, precapAudit.initialCount, keypoints.cols,
				nfeatures, threshold, block, grid, sensorId, timestamp, slotIndex, level, precapAudit);
			keypoints.cols = 0;
			CV_Error(Error::StsError, std::string("deterministic FAST pre-cap failed: ")
				+ fast_precap_detail::selectionStatusName(precapAudit.status));
		}

		precapAudit.canonicalizerApplied = true;
		precapAudit.fullCaptureCoordinates = fullCaptureHost.ptr<Vec2s>();
		CUDA_CHECK(cudaMemcpyAsync(kpLoc, fullCaptureHost.ptr<Vec2s>(),
			static_cast<std::size_t>(precapAudit.selectedCount) * sizeof(Vec2s), cudaMemcpyHostToDevice, stream));
		CUDA_CHECK(cudaStreamSynchronize(stream));
		keypoints.cols = static_cast<int>(precapAudit.selectedCount);
	}

	logCalcKeypointsFingerprint(
		image, mask, keypoints, precapAudit.initialCount, keypoints.cols, nfeatures, threshold, block, grid,
		sensorId, timestamp, slotIndex, level, precapAudit);
}

